import{_ as e,o as l,c as t,a2 as r}from"./chunks/framework.ClgMjOt7.js";const p=JSON.parse('{"title":"端末間データ同期 (PallaSync)","description":"複数端末での設定やお気に入りタグの自動同期","frontmatter":{"title":"端末間データ同期 (PallaSync)","description":"複数端末での設定やお気に入りタグの自動同期"},"headers":[],"relativePath":"user/sync.md","filePath":"user/sync.md","lastUpdated":1789105872000}'),n={name:"user/sync.md"};function s(o,a,i,c,d,_){return l(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="端末間データ同期-pallasync" tabindex="-1">端末間データ同期 (PallaSync) <a class="header-anchor" href="#端末間データ同期-pallasync" aria-label="Permalink to &quot;端末間データ同期 (PallaSync)&quot;">​</a></h1><p>PallaSync を使うと、スマホとタブレットなど複数の端末間で、アプリの設定やお気に入りタグ（ウォッチリスト）を自動的に同期・バックアップできます。</p><hr><h2 id="安全な仕組み" tabindex="-1">安全な仕組み <a class="header-anchor" href="#安全な仕組み" aria-label="Permalink to &quot;安全な仕組み&quot;">​</a></h2><ul><li><strong>暗号化して送信</strong>: 同期されるデータは、お使いの端末上で高度に暗号化されてから送信されます。</li><li><strong>サーバーでも解読不可</strong>: サーバー側には暗号化されたデータしか保存されないため、第三者にデータを見られる心配はありません。</li></ul><hr><h2 id="使い方" tabindex="-1">使い方 <a class="header-anchor" href="#使い方" aria-label="Permalink to &quot;使い方&quot;">​</a></h2><ol><li>設定画面から「PallaSync」をオンにします。</li><li>同期したい別の端末でも同じようにオンにすると、バックグラウンドで自動的に最新の状態に同期されます。</li></ol>',8)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
